/* Auto-generated: Phoenix sit pose still for neon dashboard. */
(function(){
  var b64="";
  var url="data:image/jpeg;base64,"+b64;
  function apply(){
    document.querySelectorAll("img.phoenix-still, .phoenix-still").forEach(function(el){
      if(el.dataset.phoenixSitApplied) return;
      el.dataset.phoenixSitApplied="1";
      if(el.tagName==="IMG") el.src=url;
      else el.style.backgroundImage="url("+url+")";
    });
    document.querySelectorAll("video.phoenix-vid").forEach(function(v){
      if(!v.getAttribute("poster")) v.setAttribute("poster", url);
    });
  }
  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",apply);
  else apply();
  var obs=new MutationObserver(apply);
  if(document.documentElement) obs.observe(document.documentElement,{childList:true,subtree:true,attributes:true});
})();
